  const bad = new Set(blocked.map(([r, c]) => r * n + c));
  const cols = new Set(), d1 = new Set(), d2 = new Set();
  function go(r) {
    if (r === n) return 1;
    let total = 0;
    for (let c = 0; c < n; c++) {
      if (bad.has(r * n + c) || cols.has(c) || d1.has(r - c) || d2.has(r + c)) continue;
      cols.add(c); d1.add(r - c); d2.add(r + c);
      total += go(r + 1);
      cols.delete(c); d1.delete(r - c); d2.delete(r + c);
    }
    return total;
  }
  return go(0);
